Definition only (A A' : AS) (L : list word) : Prop := forall q, ~ In q L -> live A' q = live A q.
Definition offs (A : AS) (L : list word) : Prop := forall q, In q L -> live A q = None.
Definition lives (A : AS) (L : list word) : Prop := forall q, In q L -> live A q <> None.
Definition disj (L1 L2 : list word) : Prop := forall q, In q L1 -> ~ In q L2.

