Definition wl (l : list Z) : list word := map (Z_to_bv 64) l.
Definition sel_l (sel : Z) (sv : selv) : list word := wl [sel; v_data sv; v_rows sv 0; v_rows sv 1; v_rows sv 2; v_rows sv 3; v_rows sv 4]%Z.
Definition pix_l (pix data cd arr : Z) : list word := wl (pix :: data :: (if (cd =? 0)%Z then [] else [cd; arr])).

