Section Pix.
Context {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O23Pins}.

(* [comment removed for export] *)
Definition cmx (C : lctx) (A : AS) (m : word -> option byte) (pix data cd : Z) (cvx : cmapv) : Prop :=
  cd = 0%Z \/
  (cd <> 0%Z /\ CMAPat m cd cvx /\ cmap_ok cvx /\
   live A (Z_to_bv 64 cd) = Some 24%Z /\ live A (Z_to_bv 64 (c_arr cvx)) = Some (4 * c_nalloc cvx)%Z /\
   live (c_A0 C) (Z_to_bv 64 cd) = None /\ live (c_A0 C) (Z_to_bv 64 (c_arr cvx)) = None /\
   cd <> c_arr cvx /\ cd <> pix /\ c_arr cvx <> pix /\ data <> cd /\ data <> c_arr cvx).

Definition PIXC (C : lctx) (A : AS) (m : word -> option byte) (pix w h cd data : Z) (cvx : cmapv) : Prop :=
  PIXat m pix (hdv w h 1 cd data) /\
  live A (Z_to_bv 64 pix) = Some 64%Z /\ live (c_A0 C) (Z_to_bv 64 pix) = None /\
  live A (Z_to_bv 64 data) = Some (4 * (wpl_of w 1 * h))%Z /\ live (c_A0 C) (Z_to_bv 64 data) = None /\
  data <> pix /\ cmx C A m pix data cd cvx.

