(* [comment removed for export] *)
Lemma PIXC_keep : forall C A A' m m' pix w h cd data cvx, PIXC C A m pix w h cd data cvx ->
  (forall p, In p (pix_l pix data cd (c_arr cvx)) -> live A' p = live A p) ->
  (forall x : word, (pix <= u x < pix + 64)%Z -> m' x = m x) ->
  (cd <> 0%Z -> forall x : word, (cd <= u x < cd + 24)%Z -> m' x = m x) ->
  PIXC C A' m' pix w h cd data cvx.
Proof.
