(* [comment removed for export] *)
Definition PIXO (C : lctx) (A : AS) (m : word -> option byte) (pix w h data : Z) : Prop :=
  pix = 0%Z \/ (pix <> 0%Z /\ PIXC C A m pix w h 0 data cmap0).
Definition pixo_l (pix data : Z) : list word := if (pix =? 0)%Z then [] else pix_l pix data 0 0.

Lemma PIXO_keep_blk : forall C A A' Ax (m m' : word -> option byte) pix w h data, PIXO C A m pix w h data ->
  (forall p, In p (pixo_l pix data) -> live A' p = live A p) -> (forall p, In p (pixo_l pix data) -> live Ax p = live A p) -> LIVK Ax m m' ->
